        { "to_base.dart", "const digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';\n\nString toBase(int num, int base) {\n  var result = '';\n  while (num > 0) {\n    result += digits[num % base];\n    num ~/= base;\n  }\n  return result;\n}\n\nvoid main() {\n  print('${toBase(31, 16)} ${toBase(41, 2)} ${toBase(3005, 16)}');\n}\n", "logic-dart-digits-written-backwards", 6, 6, 1, "    result = digits[num % base] + result;" },
        { "to_base.erl", "-module(to_base).\n-export([main/0]).\n\n-define(DIGITS, \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\").\n\ndigits(0, _Base, Written) -> Written;\ndigits(Num, Base, Written) -> digits(Num div Base, Base, Written ++ [lists:nth(Num rem Base + 1, ?DIGITS)]).\n\nmain() ->\n    io:format(\"~s ~s ~s~n\", [digits(31, 16, \"\"), digits(41, 2, \"\"), digits(3005, 16, \"\")]).\n", "logic-erlang-digits-written-backwards", 7, 7, 1, "digits(Num, Base, Written) -> digits(Num div Base, Base, [lists:nth(Num rem Base + 1, ?DIGITS)] ++ Written)." },
