        { "to_base.js", "const DIGITS = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n\nfunction toBase(num, base) {\n  let result = \"\";\n  while (num > 0) {\n    const digit = num % base;\n    result += DIGITS[digit];\n    num = Math.floor(num / base);\n  }\n  return result;\n}\n\nconsole.log(toBase(31, 16), toBase(41, 2), toBase(3005, 16));\n", "logic-js-digits-written-backwards", 7, 7, 1, "    result = DIGITS[digit] + result;" },
        { "to_base.lua", "local DIGITS = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n\nlocal function to_base(num, base)\n  local result = \"\"\n  while num > 0 do\n    local digit = num % base\n    result = result .. DIGITS:sub(digit + 1, digit + 1)\n    num = num // base\n  end\n  return result\nend\n\nprint(to_base(31, 16) .. \" \" .. to_base(41, 2) .. \" \" .. to_base(3005, 16))\n", "logic-lua-digits-written-backwards", 7, 7, 1, "    result = DIGITS:sub(digit + 1, digit + 1) .. result" },
