        { "to_base.rb", "DIGITS = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n\ndef to_base(num, base)\n  result = \"\"\n  while num > 0\n    result += DIGITS[num % base]\n    num /= base\n  end\n  result\nend\n\nputs \"#{to_base(31, 16)} #{to_base(41, 2)} #{to_base(3005, 16)}\"\n", "logic-ruby-digits-written-backwards", 6, 6, 1, "    result = DIGITS[num % base] + result" },
