        { "to_base.ts", "const DIGITS: string = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n\nfunction toBase(num: number, base: number): string {\n  let result: string = \"\";\n  while (num > 0) {\n    result = result + DIGITS[num % base];\n    num = Math.floor(num / base);\n  }\n  return result;\n}\n\nconsole.log(toBase(31, 16), toBase(41, 2), toBase(3005, 16));\n", "logic-js-digits-written-backwards", 6, 6, 1, "    result = DIGITS[num % base] + result;" },
