    [Theory]
    [MemberData(nameof(Mistakes))]
    public void DigitsPutAfterTheOnesBeforeThemAreFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The conversions putting each digit in front; each digit put after the ones before it and the text turned round at the
    /// end, QuixBugs' other right way; the sum of a number's digits, in whatever order they come; the digits kept in a list
    /// lowest first and read back from the end; and a StringBuilder given each digit in front.
    /// </summary>
    [Theory]
    [InlineData("Program.cs", "using System;\n\npublic static class Program\n{\n    const string Digits = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n\n    static string ToBase(int number, int radix)\n    {\n        var written = \"\";\n        while (number > 0)\n        {\n            written = Digits[number % radix] + written;\n            number /= radix;\n        }\n\n        return written;\n    }\n\n    public static void Main()\n    {\n        Console.WriteLine($\"{ToBase(31, 16)} {ToBase(41, 2)} {ToBase(3005, 16)}\");\n    }\n}\n")]
    [InlineData("to_base.cpp", "#include <iostream>\n#include <string>\n\nconst std::string DIGITS = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n\nstd::string toBase(int num, int base) {\n    std::string result;\n    while (num > 0) {\n        result = DIGITS[num % base] + result;\n        num /= base;\n    }\n    return result;\n}\n\nint main() {\n    std::cout << toBase(31, 16) << \" \" << toBase(41, 2) << \" \" << toBase(3005, 16) << std::endl;\n    return 0;\n}\n")]
    [InlineData("to_base.dart", "const digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';\n\nString toBase(int num, int base) {\n  var result = '';\n  while (num > 0) {\n    result = digits[num % base] + result;\n    num ~/= base;\n  }\n  return result;\n}\n\nvoid main() {\n  print('${toBase(31, 16)} ${toBase(41, 2)} ${toBase(3005, 16)}');\n}\n")]
