    [InlineData("to_base.exs", "defmodule Base36 do\n  @digits \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n\n  def to_base(num, base), do: digits(num, base, \"\")\n\n  defp digits(0, _base, written), do: written\n  defp digits(num, base, written), do: digits(div(num, base), base, String.at(@digits, rem(num, base)) <> written)\nend\n\nIO.puts(\"#{Base36.to_base(31, 16)} #{Base36.to_base(41, 2)} #{Base36.to_base(3005, 16)}\")\n")]
    [InlineData("to_base.f90", "module base_module\n  implicit none\n  character(len=36), parameter :: digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'\ncontains\n  function to_base(start, base) result(written)\n    integer, intent(in) :: start, base\n    character(len=32) :: written\n    integer :: num, digit\n    num = start\n    written = ''\n    do while (num > 0)\n      digit = mod(num, base)\n      written = digits(digit + 1:digit + 1) // trim(written)\n      num = num / base\n    end do\n  end function to_base\nend module base_module\n\nprogram to_base_program\n  use base_module\n  implicit none\n  print '(A, 1X, A, 1X, A)', trim(to_base(31, 16)), trim(to_base(41, 2)), trim(to_base(3005, 16))\nend program to_base_program\n")]
    [InlineData("to_base.fsx", "let digits = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n\nlet toBase start radix =\n    let mutable num = start\n    let mutable result = \"\"\n    while num > 0 do\n        result <- string digits.[num % radix] + result\n        num <- num / radix\n    result\n\nprintfn \"%s %s %s\" (toBase 31 16) (toBase 41 2) (toBase 3005 16)\n")]
    [InlineData("to_base.go", "package main\n\nimport \"fmt\"\n\nconst digits = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n\nfunc toBase(num, base int) string {\n\tresult := \"\"\n\tfor num > 0 {\n\t\tresult = string(digits[num%base]) + result\n\t\tnum /= base\n\t}\n\treturn result\n}\n\nfunc main() {\n\tfmt.Println(toBase(31, 16), toBase(41, 2), toBase(3005, 16))\n}\n")]
