    [InlineData("lowest_first.py", "# The digits kept in a list, lowest first, as the loop meets them, and read back from the end: prints 1F 101001 BBD.\nDIGITS = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\ndef to_base(num, b):\n    found = []\n    while num > 0:\n        found.append(DIGITS[num % b])\n        num //= b\n    return \"\".join(reversed(found))\n\n\nprint(to_base(31, 16), to_base(41, 2), to_base(3005, 16))\n")]
    [InlineData("Prepended.java", "// A StringBuilder given each digit in front: prints 1F 101001 BBD.\npublic class Prepended {\n    static String toBase(int num, int base) {\n        StringBuilder written = new StringBuilder();\n        while (num > 0) {\n            written.insert(0, \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\".charAt(num % base));\n            num /= base;\n        }\n        return written.toString();\n    }\n\n    public static void main(String[] args) {\n        System.out.println(toBase(31, 16) + \" \" + toBase(41, 2) + \" \" + toBase(3005, 16));\n    }\n}\n")]
    [InlineData("turned_round.py", "# Each digit put after the ones before it, and the text turned round at the end - QuixBugs' other right way: prints 1F 101001 BBD.\nimport string\ndef to_base(num, b):\n    result = ''\n    alphabet = string.digits + string.ascii_uppercase\n    while num > 0:\n        i = num % b\n        num = num // b\n        result = result + alphabet[i]\n    return result[::-1]\n\n\nprint(to_base(31, 16), to_base(41, 2), to_base(3005, 16))\n")]
    public void DigitsInTheirOwnOrderAreLeftAlone(string fileName, string code)
    {
        // Each check of the file's own language, as FixFinder runs them.
        var file = Program(fileName, code);
        var extension = Path.GetExtension(fileName).ToLowerInvariant();
        Assert.Empty(LogicPatterns.All.Where(pattern => pattern.Id.EndsWith("digits-written-backwards", StringComparison.Ordinal) && pattern.Extensions.Contains(extension))
            .SelectMany(pattern => pattern.Find(file)));
    }
}
